(async () => {
  if (typeof window.g_ck !== "string" || !window.g_ck) {
    console.log("SESSION CONTEXT: MISSING");
    return;
  }
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 15000);
  try {
    const response = await fetch(
      "/api/now/table/cmdb_ci_business_app?u_app_id=APP00005161&sysparm_fields=u_app_id,name,support_group_label,support_group_label.name,support_group_label.email&sysparm_limit=1&sysparm_display_value=all",
      {
        method: "GET",
        credentials: "same-origin",
        redirect: "error",
        cache: "no-store",
        headers: { Accept: "application/json", "X-UserToken": window.g_ck },
        signal: controller.signal
      }
    );
    console.log("HTTP: " + response.status);
    if (!response.ok) return;
    let body;
    try { body = await response.json(); }
    catch { console.log("JSON: NO"); return; }
    if (!Array.isArray(body.result)) {
      console.log("RESULT ARRAY: MISSING");
      return;
    }
    console.log("RECORDS: " + body.result.length);
    if (body.result.length !== 1) return;
    const record = body.result[0];
    const value = item => item && typeof item === "object" ? item.value : item;
    const populated = item => typeof value(item) === "string" && value(item).trim().length > 0;
    console.log("EXPECTED ID: " + (value(record.u_app_id) === "APP00005161" ? "YES" : "NO"));
    if (value(record.u_app_id) !== "APP00005161") return;
    console.log("NAME PRESENT: " + (populated(record.name) ? "YES" : "NO"));
    console.log("GROUP REFERENCE: " + (
      /^[0-9a-f]{32}$/i.test(value(record.support_group_label) || "") ? "YES" : "NO"
    ));
    console.log("GROUP NAME PRESENT: " + (populated(record["support_group_label.name"]) ? "YES" : "NO"));
    console.log("GROUP EMAIL PRESENT: " + (populated(record["support_group_label.email"]) ? "YES" : "NO"));
  } catch (error) {
    console.log(controller.signal.aborted
      ? "REQUEST: TIMED OUT" : "REQUEST: FAILED OR REDIRECTED");
  } finally {
    clearTimeout(timer);
  }
})();
